export interface MatchResult {
  customerName: string;
  rplName: string;
  similarity: number;
}

export interface RawDataRow {
  [key: string]: any;
}

export enum AppState {
  IDLE = 'IDLE',
  MAPPING = 'MAPPING',
  PROCESSING = 'PROCESSING',
  RESULTS = 'RESULTS'
}

/**
 * Computes similarity between two strings using Sorensen-Dice coefficient.
 * This is generally better for business names than pure Levenshtein.
 */
export function getSimilarity(str1: string, str2: string): number {
  const s1 = cleanString(str1);
  const s2 = cleanString(str2);

  if (s1 === s2) return 1.0;
  if (s1.length < 2 || s2.length < 2) return 0;

  const bigrams1 = getBigrams(s1);
  const bigrams2 = getBigrams(s2);

  const intersection = bigrams1.filter(b => bigrams2.includes(b)).length;
  return (2 * intersection) / (bigrams1.length + bigrams2.length);
}

function cleanString(str: string): string {
  // Normalize and remove common business suffixes for better matching
  return str
    .toLowerCase()
    .replace(/[.,\/#!$%\^&\*;:{}=\-_`~()]/g, "")
    .replace(/\s{2,}/g, " ")
    .replace(/\b(co|ltd|inc|corp|corporation|limited|technology|tech|group|int|international|trade|llc|plc)\b/g, "")
    .trim();
}

function getBigrams(str: string): string[] {
  const bigrams: string[] = [];
  for (let i = 0; i < str.length - 1; i++) {
    bigrams.push(str.substring(i, i + 2));
  }
  return bigrams;
}

import { GoogleGenAI, Type } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const geminiService = {
  /**
   * Cleans a list of names using Gemini to normalize them by removing noisy text.
   */
  async cleanNames(names: string[]): Promise<string[]> {
    try {
      const response = await ai.models.generateContent({
        model: "gemini-3-flash-preview",
        contents: `Normalize and clean the following business names. Remove legal entity suffixes (like Ltd, Co, Corp), standardizing spacing and capitalization. Keep only the core business name. Return as a JSON array of strings.\n\nNames: ${names.join(", ")}`,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: { type: Type.STRING }
          }
        }
      });
      return JSON.parse(response.text || "[]");
    } catch (error) {
      console.error("Gemini Cleaning Error:", error);
      return names; // Fallback to raw names
    }
  }
};

import React, { useCallback } from 'react';
import * as XLSX from 'xlsx';
import { Upload, FileSpreadsheet, AlertCircle } from 'lucide-react';

interface FileUploadProps {
  onDataLoaded: (data: any[], headers: string[]) => void;
  isLoading: boolean;
}

export const FileUpload: React.FC<FileUploadProps> = ({ onDataLoaded, isLoading }) => {
  const handleFile = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target?.result;
      const wb = XLSX.read(bstr, { type: 'binary' });
      const wsname = wb.SheetNames[0];
      const ws = wb.Sheets[wsname];
      const data = XLSX.utils.sheet_to_json(ws, { header: 1 }) as any[][];

      if (data.length > 0) {
        const headers = data[0].map(h => String(h));
        const rows = data.slice(1).map(row => {
          const obj: any = {};
          headers.forEach((h, i) => {
            obj[h] = row[i];
          });
          return obj;
        });
        onDataLoaded(rows, headers);
      }
    };
    reader.readAsBinaryString(file);
  }, [onDataLoaded]);

  return (
    <div className="w-full">
      <label className={`
        flex flex-col items-center justify-center w-full h-64 border-2 border-dashed rounded-xl cursor-pointer
        transition-all duration-200 group
        ${isLoading ? 'bg-gray-50 border-gray-300 pointer-events-none' : 'bg-white border-blue-200 hover:border-blue-400 hover:bg-blue-50/30'}
      `}>
        <div className="flex flex-col items-center justify-center pt-5 pb-6">
          <div className="p-4 mb-4 rounded-full bg-blue-100 text-blue-600 group-hover:scale-110 transition-transform">
            <FileSpreadsheet size={32} />
          </div>
          <p className="mb-2 text-sm text-gray-700 font-medium">
            <span className="font-bold">Click to upload</span> or drag and drop
          </p>
          <p className="text-xs text-gray-500">Excel (.xlsx, .xls) or CSV files</p>
        </div>
        <input type="file" className="hidden" accept=".xlsx, .xls, .csv" onChange={handleFile} />
      </label>

      <div className="mt-4 flex items-start gap-2 p-3 bg-amber-50 rounded-lg border border-amber-100 text-amber-800 text-xs">
        <AlertCircle size={14} className="mt-0.5 flex-shrink-0" />
        <p>Ensure your file has clearly labeled columns for 'Customer Names' and 'RPL Names'. You can have both in the same file or mapping across lists.</p>
      </div>
    </div>
  );
};

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  Search, 
  Download, 
  RefreshCw, 
  CheckCircle2, 
  AlertTriangle,
  FileSearch,
  ChevronRight,
  Info,
  ArrowRightLeft
} from 'lucide-react';
import { FileUpload } from './components/FileUpload';
import { getSimilarity } from './utils/fuzzy';
import { MatchResult, RawDataRow, AppState } from './types';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [rawData, setRawData] = useState<RawDataRow[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [customerCol, setCustomerCol] = useState<string>('');
  const [rplCol, setRplCol] = useState<string>('');
  const [results, setResults] = useState<MatchResult[]>([]);
  const [processingProgress, setProcessingProgress] = useState(0);
  const [threshold, setThreshold] = useState(0.5);

  const reset = () => {
    setAppState(AppState.IDLE);
    setRawData([]);
    setHeaders([]);
    setResults([]);
    setCustomerCol('');
    setRplCol('');
  };

  const handleDataLoaded = (data: RawDataRow[], cols: string[]) => {
    setRawData(data);
    setHeaders(cols);
    setAppState(AppState.MAPPING);

    // Auto-detect columns if possible
    const cust = cols.find(c => /customer|client|name/i.test(c));
    const rpl = cols.find(c => /rpl|restricted|denied|sanction/i.test(c));
    if (cust) setCustomerCol(cust);
    if (rpl) setRplCol(rpl);
  };

  const startProcessing = async () => {
    if (!customerCol || !rplCol) return;
    setAppState(AppState.PROCESSING);
    setProcessingProgress(0);

    const matches: MatchResult[] = [];
    const uniqueCustomers = Array.from(new Set(rawData.map(r => String(r[customerCol])).filter(Boolean)));
    const uniqueRPLs = Array.from(new Set(rawData.map(r => String(r[rplCol])).filter(Boolean)));

    // For better UX, we'll process in chunks to show progress
    const total = uniqueCustomers.length;

    for (let i = 0; i < total; i++) {
      const cust = uniqueCustomers[i];
      let bestMatch = "";
      let bestScore = 0;

      // Basic local fuzzy match
      for (const rpl of uniqueRPLs) {
        const score = getSimilarity(cust, rpl);
        if (score > bestScore) {
          bestScore = score;
          bestMatch = rpl;
        }
        if (bestScore === 1) break;
      }

      matches.push({
        customerName: cust,
        rplName: bestMatch,
        similarity: parseFloat(bestScore.toFixed(4))
      });

      if (i % 10 === 0 || i === total - 1) {
        setProcessingProgress(Math.round(((i + 1) / total) * 100));
        // Small delay to allow UI to breathe
        await new Promise(r => setTimeout(r, 0));
      }
    }

    setResults(matches.sort((a, b) => b.similarity - a.similarity));
    setAppState(AppState.RESULTS);
  };

  const exportToExcel = () => {
    const ws = XLSX.utils.json_to_sheet(results.map(r => ({
      'Customer Name': r.customerName,
      'RPL Name': r.rplName,
      'Similarity': r.similarity
    })));
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Fuzzy Results");
    XLSX.writeFile(wb, "fuzzy_lookup_results.xlsx");
  };

  const filteredResults = useMemo(() => {
    return results.filter(r => r.similarity >= threshold);
  }, [results, threshold]);

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-white border-b sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center">
              <Search className="text-white" size={18} />
            </div>
            <h1 className="text-xl font-bold text-gray-900 tracking-tight">FuzzyMatch<span className="text-blue-600">Pro</span></h1>
          </div>
          <div className="flex items-center gap-4">
            <button 
              onClick={reset}
              className="text-sm font-medium text-gray-500 hover:text-gray-700 transition-colors"
            >
              Start Over
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-8">
        {/* State: IDLE - Upload */}
        {appState === AppState.IDLE && (
          <div className="max-w-2xl mx-auto">
            <div className="text-center mb-8">
              <h2 className="text-3xl font-extrabold text-gray-900 mb-3">Lookup Restricted Parties</h2>
              <p className="text-gray-600">Upload your customer database to find similar matches against Restricted Party Lists (RPL).</p>
            </div>
            <FileUpload onDataLoaded={handleDataLoaded} isLoading={false} />
          </div>
        )}

        {/* State: MAPPING */}
        {appState === AppState.MAPPING && (
          <div className="max-w-3xl mx-auto bg-white rounded-2xl shadow-sm border p-8">
            <div className="flex items-center gap-3 mb-6">
              <ArrowRightLeft className="text-blue-600" />
              <h2 className="text-xl font-bold">Map Columns</h2>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
              <div className="space-y-2">
                <label className="block text-sm font-semibold text-gray-700">Customer Name Column</label>
                <select 
                  value={customerCol}
                  onChange={(e) => setCustomerCol(e.target.value)}
                  className="w-full p-3 border rounded-lg bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                >
                  <option value="">Select Column...</option>
                  {headers.map(h => <option key={h} value={h}>{h}</option>)}
                </select>
                <p className="text-xs text-gray-500">The field containing your internal customer database.</p>
              </div>

              <div className="space-y-2">
                <label className="block text-sm font-semibold text-gray-700">RPL Name Column</label>
                <select 
                  value={rplCol}
                  onChange={(e) => setRplCol(e.target.value)}
                  className="w-full p-3 border rounded-lg bg-gray-50 focus:ring-2 focus:ring-blue-500 focus:outline-none"
                >
                  <option value="">Select Column...</option>
                  {headers.map(h => <option key={h} value={h}>{h}</option>)}
                </select>
                <p className="text-xs text-gray-500">The field containing the restricted party entries.</p>
              </div>
            </div>

            <div className="p-4 bg-blue-50 rounded-xl mb-8 flex items-start gap-3">
              <Info className="text-blue-500 mt-0.5 flex-shrink-0" size={18} />
              <div className="text-sm text-blue-800">
                <p className="font-semibold mb-1">How it works:</p>
                <p>We'll perform a fuzzy comparison between every unique customer name and every unique RPL entry using the Sorensen-Dice algorithm. This is robust against typos and common business name variations.</p>
              </div>
            </div>

            <button
              disabled={!customerCol || !rplCol}
              onClick={startProcessing}
              className={`w-full py-4 rounded-xl font-bold text-lg shadow-lg transition-all
                ${(!customerCol || !rplCol) 
                  ? 'bg-gray-200 text-gray-400 cursor-not-allowed' 
                  : 'bg-blue-600 text-white hover:bg-blue-700 active:scale-95'
                }`}
            >
              Start Matching Analysis
            </button>
          </div>
        )}

        {/* State: PROCESSING */}
        {appState === AppState.PROCESSING && (
          <div className="max-w-md mx-auto text-center py-20">
            <RefreshCw className="mx-auto text-blue-600 animate-spin mb-6" size={48} />
            <h2 className="text-2xl font-bold text-gray-900 mb-2">Analyzing Data...</h2>
            <p className="text-gray-500 mb-8">Comparing customer records with restricted lists.</p>

            <div className="w-full bg-gray-100 rounded-full h-4 mb-4">
              <div 
                className="bg-blue-600 h-4 rounded-full transition-all duration-300" 
                style={{ width: `${processingProgress}%` }}
              ></div>
            </div>
            <p className="text-sm font-mono text-gray-400">{processingProgress}% Complete</p>
          </div>
        )}

        {/* State: RESULTS */}
        {appState === AppState.RESULTS && (
          <div className="space-y-6">
            <div className="flex flex-col md:flex-row md:items-end justify-between gap-4">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">Analysis Results</h2>
                <p className="text-gray-500">Found {results.length} matches across your dataset.</p>
              </div>
              <div className="flex items-center gap-4">
                <div className="flex flex-col gap-1">
                  <label className="text-xs font-bold text-gray-500 uppercase tracking-wider">Similarity Threshold</label>
                  <div className="flex items-center gap-3">
                    <input 
                      type="range" 
                      min="0" 
                      max="1" 
                      step="0.05" 
                      value={threshold}
                      onChange={(e) => setThreshold(parseFloat(e.target.value))}
                      className="w-32 h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer accent-blue-600"
                    />
                    <span className="text-sm font-mono font-bold bg-white px-2 py-1 border rounded shadow-sm w-12 text-center">
                      {threshold.toFixed(2)}
                    </span>
                  </div>
                </div>
                <button
                  onClick={exportToExcel}
                  className="flex items-center gap-2 bg-emerald-600 text-white px-6 py-2.5 rounded-lg font-bold hover:bg-emerald-700 transition-colors shadow-md shadow-emerald-200"
                >
                  <Download size={18} />
                  Export Excel
                </button>
              </div>
            </div>

            <div className="bg-white border rounded-2xl shadow-sm overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead>
                    <tr className="bg-gray-50 border-b">
                      <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Customer Name</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider">Closest RPL Match</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Similarity</th>
                      <th className="px-6 py-4 text-xs font-bold text-gray-500 uppercase tracking-wider text-center">Risk Level</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y">
                    {filteredResults.length > 0 ? (
                      filteredResults.map((result, idx) => (
                        <tr key={idx} className="hover:bg-gray-50 transition-colors group">
                          <td className="px-6 py-4 font-medium text-gray-900">{result.customerName}</td>
                          <td className="px-6 py-4 text-gray-600">{result.rplName}</td>
                          <td className="px-6 py-4 text-center">
                            <span className={`inline-block px-3 py-1 rounded-full text-sm font-mono font-bold border ${
                              result.similarity > 0.8 ? 'bg-red-50 text-red-700 border-red-100' :
                              result.similarity > 0.5 ? 'bg-amber-50 text-amber-700 border-amber-100' :
                              'bg-green-50 text-green-700 border-green-100'
                            }`}>
                              {result.similarity.toFixed(4)}
                            </span>
                          </td>
                          <td className="px-6 py-4">
                            <div className="flex justify-center">
                              {result.similarity > 0.85 ? (
                                <div className="flex items-center gap-1.5 text-red-600 font-bold text-xs uppercase bg-red-50 px-2 py-1 rounded border border-red-100">
                                  <AlertTriangle size={14} /> Critical Match
                                </div>
                              ) : result.similarity > 0.65 ? (
                                <div className="flex items-center gap-1.5 text-amber-600 font-bold text-xs uppercase bg-amber-50 px-2 py-1 rounded border border-amber-100">
                                  <Info size={14} /> High Potential
                                </div>
                              ) : (
                                <div className="flex items-center gap-1.5 text-blue-500 font-bold text-xs uppercase bg-blue-50 px-2 py-1 rounded border border-blue-100">
                                  <CheckCircle2 size={14} /> Low Similarity
                                </div>
                              )}
                            </div>
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan={4} className="px-6 py-20 text-center">
                          <div className="max-w-xs mx-auto text-gray-400">
                            <FileSearch size={48} className="mx-auto mb-4 opacity-20" />
                            <p className="text-lg font-medium">No results found above {threshold}</p>
                            <p className="text-sm">Try lowering the similarity threshold slider.</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>

            <div className="flex items-center justify-between text-sm text-gray-500 bg-gray-50 p-4 rounded-xl border">
              <div className="flex gap-4">
                <span>Showing {filteredResults.length} of {results.length} unique records</span>
                <span className="opacity-50">|</span>
                <span>Algorithm: Sorensen-Dice (Bigram)</span>
              </div>
              <div className="flex gap-2 items-center">
                <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                <span className="font-semibold text-gray-700">Ready for Audit</span>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer / Persistent Call-to-action */}
      {appState === AppState.RESULTS && (
        <div className="fixed bottom-0 left-0 right-0 bg-white border-t p-4 shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.1)] flex justify-center z-10">
           <div className="max-w-7xl w-full flex items-center justify-between px-4">
             <div className="hidden sm:block text-sm text-gray-500">
               Audit your restricted party matching results and export to share with your compliance team.
             </div>
             <div className="flex gap-3">
               <button 
                 onClick={reset}
                 className="px-6 py-2 rounded-lg border font-bold text-gray-600 hover:bg-gray-50"
               >
                 New Dataset
               </button>
               <button 
                 onClick={exportToExcel}
                 className="px-8 py-2 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 shadow-lg shadow-blue-200 flex items-center gap-2"
               >
                 Download Full Report <ChevronRight size={18} />
               </button>
             </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import * as XLSX from 'xlsx';
import { 
  Search, 
  Download, 
  RefreshCw, 
  CheckCircle2, 
  AlertTriangle,
  FileSearch,
  ChevronRight,
  Info,
  ArrowRightLeft,
  Table as TableIcon,
  Eye
} from 'lucide-react';
import { FileUpload } from './components/FileUpload';
import { getSimilarity } from './utils/fuzzy';
import { RawDataRow, AppState } from './types';

interface ExtendedMatchResult {
  originalRow: RawDataRow;
  customerName: string;
  rplMatch: string;
  similarity: number;
}

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [rawData, setRawData] = useState<RawDataRow[]>([]);
  const [headers, setHeaders] = useState<string[]>([]);
  const [customerCol, setCustomerCol] = useState<string>('');
  const [rplCol, setRplCol] = useState<string>('');
  const [results, setResults] = useState<ExtendedMatchResult[]>([]);
  const [processingProgress, setProcessingProgress] = useState(0);
  const [threshold, setThreshold] = useState(0.5);
  const [showPreview, setShowPreview] = useState(false);

  const reset = () => {
    setAppState(AppState.IDLE);
    setRawData([]);
    setHeaders([]);
    setResults([]);
    setCustomerCol('');
    setRplCol('');
    setShowPreview(false);
  };

  const handleDataLoaded = (data: RawDataRow[], cols: string[]) => {
    setRawData(data);
    setHeaders(cols);
    setAppState(AppState.MAPPING);

    // Auto-detect columns
    const cust = cols.find(c => /customer|client|name|entity/i.test(c));
    const rpl = cols.find(c => /rpl|restricted|denied|sanction|watch/i.test(c));
    if (cust) setCustomerCol(cust);
    if (rpl) setRplCol(rpl);
  };

  const startProcessing = async () => {
    if (!customerCol || !rplCol) return;
    setAppState(AppState.PROCESSING);
    setProcessingProgress(0);

    const matches: ExtendedMatchResult[] = [];

    // We keep unique RPL entries to speed up the cross-lookup, 
    // but we process EVERY row in the raw data (no deduplication of customers).
    const uniqueRPLs = Array.from(new Set(rawData.map(r => String(r[rplCol] || '')).filter(Boolean)));
    const total = rawData.length;

    for (let i = 0; i < total; i++) {
      const row = rawData[i];
      const cust = String(row[customerCol] || '');
      let bestMatch = "";
      let bestScore = 0;

      if (cust.trim()) {
        for (const rpl of uniqueRPLs) {
          const score = getSimilarity(cust, rpl);
          if (score > bestScore) {
            bestScore = score;
            bestMatch = rpl;
          }
          if (bestScore === 1.0) break;
        }
      }

      matches.push({
        originalRow: row,
        customerName: cust,
        rplMatch: bestMatch,
        similarity: parseFloat(bestScore.toFixed(4))
      });

      if (i % 25 === 0 || i === total - 1) {
        setProcessingProgress(Math.round(((i + 1) / total) * 100));
        await new Promise(r => setTimeout(r, 0));
      }
    }

    setResults(matches);
    setAppState(AppState.RESULTS);
  };

  const exportToExcel = () => {
    // Construct export data: Original Columns + Match Results
    const exportData = results.map(r => ({
      ...r.originalRow,
      'MATCHED_RPL_NAME': r.rplMatch,
      'MATCH_SIMILARITY': r.similarity,
      'RISK_LEVEL': r.similarity > 0.85 ? 'CRITICAL' : r.similarity > 0.65 ? 'HIGH' : 'LOW'
    }));

    const ws = XLSX.utils.json_to_sheet(exportData);
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, "Fuzzy Results Full");
    XLSX.writeFile(wb, "fuzzy_lookup_full_report.xlsx");
  };

  const filteredResults = useMemo(() => {
    return results.filter(r => r.similarity >= threshold);
  }, [results, threshold]);

  return (
    <div className="min-h-screen pb-20">
      <header className="bg-white border-b sticky top-0 z-10">
