                  onClick={() => setShowPreview(!showPreview)}
                  className="flex items-center gap-2 text-sm font-semibold text-indigo-600 hover:text-indigo-700"
                >
                  <Eye size={16} />
                  {showPreview ? 'Hide Raw Data' : 'Preview Raw Data'}
                </button>
              </div>

